import java.io.BufferedReader
import java.io.InputStreamReader
import kotlin.io.readText

fun main() {
    val reader = BufferedReader(InputStreamReader(System.`in`))
    val input = reader.readText().trim().split("\n").map { it.trim() }.filter { it.isNotEmpty() }

    if (input.isEmpty()) return

    var index = 0
    val firstLine = input[index++].split(" ")
    val v = firstLine[0].toInt()
    val e = firstLine[1].toInt()

    if (e == 0) {
        println(0)
        return
    }
    if (v <= 6) {
        println(e)
        return
    }

    val adj = Array(v + 1) { mutableListOf<Int>() }

    repeat(e) {
        if (index >= input.size) return
        val edge = input[index++].split(" ")
        val a = edge[0].toInt()
        val b = edge[1].toInt()
        adj[a].add(b)
        adj[b].add(a)
    }

    var f = false
    var noOfVertices = 20

    for (j in 1..7) {
        val a7 = adj[j]
        for (i in 1..7) {
            if (i == j) continue
            val other = adj[i]
            val x = a7.filter { it in other }
            if (x.isEmpty()) {
                f = true
                break
            } else if (x.size < noOfVertices) {
                noOfVertices = x.size
            }
        }
        if (f) break
    }

    if (f) {
        println(e)
    } else {
        println(e - noOfVertices)
    }
}

import java.util.Scanner

fun main() {
    val scanner = Scanner(System.`in`)
    val v = scanner.nextInt()
    val e = scanner.nextInt()

    if (e == 0) {
        println(0)
        return
    }
    if (v <= 6) {
        println(e)
        return
    }

    val adj = List(v + 1) { mutableListOf<Int>() }
    repeat(e) {
        val a = scanner.nextInt()
        val b = scanner.nextInt()
        adj[a].add(b)
        adj[b].add(a)
    }

    var f = false
    var noOfVertices = Int.MAX_VALUE

    for (j in 1..7) {
        val neighborsJ = adj[j].toSet()
        for (i in 1..7) {
            if (i == j) continue
            val neighborsI = adj[i].toSet()
            val intersection = neighborsJ.intersect(neighborsI)
            if (intersection.isEmpty()) {
                f = true
                break
            } else {
                noOfVertices = minOf(noOfVertices, intersection.size)
            }
        }
        if (f) break
    }

    if (f) {
        println(e)
    } else {
        println(e - noOfVertices)
    }
}

